'use strict';
const E=Engine,BT=Backtest,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const NAMES={USD_JPY:'米ドル / 円',EUR_JPY:'ユーロ / 円',GBP_JPY:'ポンド / 円',AUD_JPY:'豪ドル / 円',EUR_USD:'ユーロ / 米ドル'};
const LABEL={USD_JPY:'USD/JPY',EUR_JPY:'EUR/JPY',GBP_JPY:'GBP/JPY',AUD_JPY:'AUD/JPY',EUR_USD:'EUR/USD'};
let state={version:1,pair:'USD_JPY',settings:{mode:'auto',model:'',refresh:60,reminders:false},markets:{},events:[],history:[],ladder:{},calendarAt:0,handledJob:'',latest:{}};
let page='forecast',day=E.defaultDay(Date.now()),roundId='',followCurrent=true,analysis=null,auth={},models=[],working=false,job={},loading=false,calendarLoading=false,saveTimer,toastTimer,priceError='',backtestResult=null,modelsAccount='';
const pending=new Map();let serial=0,localBacktest=false,localCancel=false;
function call(action,data={}){return new Promise((resolve,reject)=>{if(!window.Native){if(action==='loadState')return resolve({});if(action==='getStatus')return resolve({auth:{profiles:[]},working:false,job:{}});if(action==='saveState')return resolve({});return reject(Error('この操作はAndroidアプリで利用できます。画面確認は設定のデモを使用してください。'));}const id=String(++serial);pending.set(id,{resolve,reject});Native.call(id,action,JSON.stringify(data));});}
window.__nativeResult=(id,out,error)=>{const p=pending.get(id);if(!p)return;pending.delete(id);error?p.reject(Error(error)):p.resolve(out);};
function persist(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem('aiforecast-v1',JSON.stringify(state));}catch{}call('saveState',state).catch(e=>toast('保存できませんでした: '+e.message));},450);}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
const fmt=(x,p=state.pair)=>Number.isFinite(+x)&&x!==null?(+x).toFixed(p==='EUR_USD'?5:3):'—';
const pct=x=>Number.isFinite(x)?x>0&&x<.001?'<0.1%':x<1&&x>.999?'>99.9%':(x*100).toFixed(1)+'%':'—';
const yen=x=>Number.isFinite(x)?(x>=0?'+':'−')+Math.abs(x).toFixed(0)+'円':'—';
const time=t=>Number.isFinite(+t)&&t!==null?new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(+t)):'時刻未定';
const date=t=>new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',month:'numeric',day:'numeric',weekday:'short'}).format(new Date(+t));
const full=t=>date(t)+' '+time(t);
const sign=x=>x>0?'up':x<0?'down':'neutral';
const ago=t=>!t?'未取得':Math.max(0,Math.floor((Date.now()-t)/60000))<1?'たった今':Math.floor((Date.now()-t)/60000)+'分前';
function connected(){return (auth.profiles||[]).find(p=>p.id===auth.active&&p.sharing);}
function currentMarket(){return state.markets[state.pair];}
function relevantEvents(){return state.events.filter(e=>E.eventRelevant(e,state.pair)).sort((a,b)=>(a.time??Infinity)-(b.time??Infinity));}
function rounds(){return E.schedule(day,state.settings.mode);}
function selectedRound(){if(followCurrent)day=E.defaultDay(Date.now(),state.settings.mode);let r=rounds(),chosen=r.find(x=>x.id===roundId);if(!chosen||followCurrent&&chosen.expiry<=Date.now()){chosen=r.find(x=>x.expiry>Date.now())||r[0];roundId=chosen?.id||'';}return chosen;}
function recompute(){try{let m=currentMarket();analysis=m?E.analyze(m.candles,m.ticker,state.pair,Date.now(),!!m.demo):null;}catch(e){analysis=null;if(currentMarket())priceError=e.message;}}
function activeAI(){let a=state.latest[state.pair];return a&&a.source==='ai'&&Date.now()-a.generatedAt<5*60000&&a.demo===!!currentMarket()?.demo?a:null;}
function forecast(timeMs){if(!analysis?.ready||Date.now()-analysis.asOf>120000||timeMs<=Date.now())return null;let a=activeAI(),f=a?.forecasts.find(x=>Math.abs(x.time-timeMs)<1000);return f||E.forecastAt(analysis,timeMs,relevantEvents());}
function targets(){let base=Math.ceil(Date.now()/60000)*60000;const ts=[5,15,30,60,120].map(m=>base+m*60000),r=selectedRound();if(r&&r.expiry>Date.now()&&r.expiry-Date.now()<=E.DAY)ts.push(r.expiry);return [...new Set(ts)].sort((a,b)=>a-b);}
function rows(){let a=activeAI(),r=selectedRound();let ts=a?a.forecasts.map(x=>x.time).filter(t=>t>Date.now()):targets();if(r&&r.expiry>Date.now()&&!ts.includes(r.expiry))ts.push(r.expiry);return ts.sort((a,b)=>a-b).map(forecast).filter(Boolean);}
function ladder(){const r=selectedRound(),key=state.pair+'|'+(r?.id||day);if(!state.ladder[key])state.ladder[key]=[{strike:'',call:'',put:''}];return state.ladder[key];}
function nav(p){page=p;render();window.scrollTo(0,0);}
function pill(text,kind=''){return `<span class="badge ${kind}">${esc(text)}</span>`;}
function button(text,action,cls='',attrs=''){return `<button class="button ${cls}" data-action="${action}" ${attrs}>${text}</button>`;}
function render(){
 let p=connected();$('#accountChip').innerHTML=`<i class="dot ${p?'on':''}"></i>${p?'ChatGPT 接続済み':auth.signingIn?'ログイン中…':'ChatGPT 未接続'}`;
 $$('.bottom button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
 let html=working?`<div class="jobbar"><span><i class="spin">◌</i> ${esc(jobLabel())}</span>${button('停止','stop','ghost small')}</div>`:'';
 if(state.lastJobError)html+=`<div class="banner warn"><p>前回の分析：${esc(state.lastJobError)}</p>${button('閉じる','dismissError','ghost small')}</div>`;
 if(page==='forecast')html+=forecastPage();else if(page==='events')html+=eventsPage();else if(page==='history')html+=historyPage();else html+=settingsPage();
 $('#content').innerHTML=html;if(page==='forecast'){drawChart();const bar=$('.roundbar'),chosen=$('.round.selected');if(bar&&chosen)bar.scrollLeft=chosen.offsetLeft-bar.offsetLeft-bar.clientWidth/2+chosen.clientWidth/2;}tick();
}
function forecastPage(){
 const a=analysis,r=selectedRound(),f=r?forecast(r.expiry):null,m=currentMarket(),ev=relevantEvents().find(e=>e.time>Date.now()),ai=activeAI();
 let hist=a?.candles||[],past=hist.length>60?hist[hist.length-60].c:a?.price,change=a? a.price-past:0;
 let reasons=priceError?`<div class="banner warn">${esc(priceError)}</div>`:'';
 if(m?.demo)reasons+=`<div class="banner demo">デモ表示 · 価格・イベントは架空です。実際の分析には「実データに戻る」を押してください。 ${button('戻る','live','ghost small')}</div>`;
 if(a&&!a.ready)reasons+=`<div class="banner warn">${esc(a.reason)}。チャートは参考履歴です。未来の予測と期待損益は表示しません。</div>`;
 if(m?.warning)reasons+=`<div class="banner warn">${esc(m.warning)}</div>`;
 let forecastTable=rows().map(x=>`<tr><td><strong>${time(x.time)}</strong><small>${r?.expiry===x.time?'第'+r.number+'回 判定':Math.round((x.time-Date.now())/60000)+'分後'}</small></td><td class="right"><strong>${fmt(x.p50)}</strong><small class="${sign(x.p50-(a?.price||0))}">${x.p50>=(a?.price||0)?'↗︎':'↘︎'} ${fmt(x.p50-(a?.price||0))}</small></td><td class="right">${fmt(x.p10)}<br>${fmt(x.p90)}</td><td class="right"><span class="badge ${x.source==='ai'?'mint':''}">${x.source==='ai'?'GPT':'統計'}</span></td></tr>`).join('');
 return `<div class="pagehead"><div><p class="eyebrow">RAKU-OP · ANALYSIS</p><h1>回号別の為替予測</h1></div>${button(loading?'<span class="spin">◌</span> 更新中':'↻ 更新','refresh','secondary',loading?'disabled':'')}</div>
 <div class="pairbar">${E.PAIRS.map(p=>`<button class="pairbutton ${p===state.pair?'selected':''}" data-action="pair" data-pair="${p}">${LABEL[p]}</button>`).join('')}</div>${reasons}
 <div class="spaced"><span class="fine">判定回号 · 日本時間 ${r?.summer?'夏時間':'標準時間'}</span><div class="toolbar roundcontrols">${button('現在','currentRound','ghost small')}<input class="dateinput" aria-label="取引日" type="date" id="tradingDay" value="${day}"></div></div>
 <div class="roundbar">${rounds().map(x=>`<button class="round ${x.id===r?.id?'selected':''} ${x.expiry<Date.now()?'past':''}" data-action="round" data-id="${x.id}"><span>第${x.number}回</span><strong>${time(x.expiry)}</strong><span>${E.roundStatus(x,Date.now())}</span></button>`).join('')||'<p class="fine">土日は回号がありません。別の日付を選択してください。</p>'}</div>
 <div class="forecastAction"><div><small>${r?time(r.expiry)+' 判定の予測中央値':'判定予測'}</small><strong class="number">${f?fmt(f.p50):'—'}</strong></div>${button(working?'分析中…':'✧ GPTで分析','analyze','',working||!a?.ready?'disabled':'')}</div>
 <div class="grid"><div class="stack"><section class="card hero"><div class="priceRow"><div><div class="statusline"><span>${NAMES[state.pair]}</span>${m?.demo?pill('DEMO','amber'):a?pill(a.quoteStatus==='OPEN'?'配信中':'休場',a.quoteStatus==='OPEN'?'mint':''):pill('データ未取得')}</div><div class="price">${a?fmt(a.price):'—'}<span>${state.pair==='EUR_USD'?'USD':'JPY'}</span></div><div class="delta ${sign(change)}">${a?(change>=0?'+':'')+fmt(change)+'（直近60本比）':'レートを取得してください'}</div></div><div style="text-align:right"><small>最終レート</small><p class="mono">${a?time(a.asOf):'—'}</p><small>${a?date(a.asOf):'日本時間'}</small></div></div>
 ${a?'<svg id="chart" class="chart" role="img" aria-label="確定した為替レートと今後の予測範囲"></svg>':'<div class="emptychart"><span>為替データを取得すると<br>価格と予測範囲を表示します</span>'+button('データを更新','refresh','small secondary')+'</div>'}
 <div class="legend"><span><i></i>参考レート</span><span><i class="fan"></i>10–90%分位の推定範囲</span><span><i class="strike"></i>目標レート</span></div><p class="fine source-note">${esc(m?.source||'GMOコイン 公開FXデータ')}<br>楽天の判定価格とは異なります。予測範囲は実測で校正されていません。</p></section>
 <section class="card"><div class="cardhead"><h2>時間帯別の予測価格</h2>${pill(ai?'GPT分析あり':'統計ベース',ai?'mint':'')}</div><div class="tablewrap"><table><thead><tr><th>時刻 / 判定</th><th class="right">中央値</th><th class="right">下側10% / 上側90%</th><th class="right">算出</th></tr></thead><tbody>${forecastTable||'<tr><td colspan="4" class="tableempty">有効な最新データがある時間だけ予測します。</td></tr>'}</tbody></table></div><div class="actionrow">${button('予測を保存','snapshot','ghost',!a?.ready?'disabled':'')}${button('送信内容','prompt','ghost')}</div></section>
 </div><div class="stack"><section class="card"><div class="cardhead"><h2>${r?'第'+r.number+'回の判定予測':'判定予測'}</h2>${pill(f?.source==='ai'?'GPT推定':'統計モデル',f?.source==='ai'?'mint':'')}</div><div class="spaced"><span class="fine">${r?date(r.expiry)+' '+time(r.expiry):'—'} 判定</span><span id="countdown" class="fine"></span></div><div class="forecastLarge ${f?sign(f.p50-a.price):'neutral'}">${f?fmt(f.p50):'—'} <span style="font-size:12px;font-weight:400;color:var(--muted)">予測中央値</span></div><p class="fine">${f?'現在から '+(f.p50>=a.price?'+':'')+fmt(f.p50-a.price)+' / 方向の強さは未検証':'最新レートと有効な回号が必要です'}</p><div class="range"><div><span>下側10%分位</span><strong>${f?fmt(f.p10):'—'}</strong></div><div style="text-align:right"><span>上側90%分位</span><strong>${f?fmt(f.p90):'—'}</strong></div></div>
 ${ev?`<button class="nextEvent" data-action="eventDetail" data-id="${esc(ev.id)}" style="width:100%;text-align:left"><span class="time">${time(ev.time)}<small>${date(ev.time)}</small></span><span class="body"><span class="watchhint">次の関連イベント</span><br>${esc(ev.title)}</span><span>›</span></button>`:'<p class="fine mt">予定を取得すると、次の関連イベントを表示します。</p>'}
 <p class="fine mt">${connected()?'ChatGPTプランの利用枠を消費します。':'設定でChatGPTに接続すると利用できます。'} 分析は別画面でも継続します。</p></section>
 ${oddsCard(f)}
 </div></div>
 <section class="card sectiongap"><div class="cardhead"><h2>テクニカル指標</h2><span class="fine">確定足から計算</span></div>${a?`<div class="indicators"><div class="indicator"><small>EMA 9 / 21 / 50</small><strong>${a.ind.trend}</strong><small>${fmt(a.ind.ema9)} / ${fmt(a.ind.ema21)}</small></div><div class="indicator"><small>RSI (14)</small><strong>${a.ind.rsi.toFixed(1)}</strong><small>${a.ind.rsi>70?'買われ過ぎ領域':a.ind.rsi<30?'売られ過ぎ領域':'中立領域'}</small></div><div class="indicator"><small>MACD ヒストグラム</small><strong class="${sign(a.ind.hist)}">${fmt(a.ind.hist)}</strong><small>12 / 26 / 9</small></div><div class="indicator"><small>ATR (14)</small><strong>${fmt(a.ind.atr)}</strong><small>1分足の平均変動幅</small></div></div><div class="two mt"><div class="fine">直近60本の支持帯 <b>${fmt(a.ind.support)}</b><br>抵抗帯 <b>${fmt(a.ind.resistance)}</b></div><div class="fine">ボリンジャー (20, 2σ)<br>${fmt(a.ind.bbLow)} – ${fmt(a.ind.bbHigh)}</div></div><div class="toolbar mt">${a.multi.map(x=>pill(x.minutes+'分足 '+(x.ind?.trend||'本数不足'))).join('')}</div>`:'<p class="fine">更新するとEMA・RSI・MACD・ATR・ボリンジャーバンドを計算します。</p>'}</section>
 ${ai?`<section class="card"><div class="cardhead"><h2>GPTの分析</h2><span class="fine">${full(ai.generatedAt)}</span></div><p class="summary">${esc(ai.summary)}</p>${analysisLists(ai)}<p class="note mt">予測の見直し条件：${esc(ai.invalidation||'明示なし')}</p>${scenarioHTML(ai.eventScenarios||[])}</section>`:''}
 <p class="fine">予定表は通常の回号です。休止・変更は楽天の取引画面で確認してください。1枚のペイアウトは1,000円。権利行使価格以上でコール、未満でプットが成立します。</p>`;
}
function oddsCard(f){
 const l=ladder(),row=l[0]||{},k=+row.strike,p=f&&row.strike?E.probability(f,k,analysis.tick):null,callPay=row.call?E.payoff(p,+row.call):null,putPay=row.put?E.payoff(p===null?null:1-p,+row.put):null;
 const closed=selectedRound()&&E.roundStatus(selectedRound(),Date.now())!=='購入可能';
 return `<section class="card"><div class="cardhead"><h2>目標レートとの比較</h2>${button('一覧','ladder','ghost small')}</div><label>楽天画面の目標レート<input id="strike" inputmode="decimal" type="number" step="${state.pair==='EUR_USD'?'0.0001':'0.01'}" placeholder="目標レートを入力" value="${esc(row.strike)}"></label><div class="two"><label>上（コール）購入価格 / 円<input id="callPrice" type="number" inputmode="decimal" min="1" max="999" placeholder="例 520" value="${esc(row.call)}"></label><label>下（プット）購入価格 / 円<input id="putPrice" type="number" inputmode="decimal" min="1" max="999" placeholder="例 530" value="${esc(row.put)}"></label></div><div id="oddsResult">${oddsResult(p,callPay,putPay,closed)}</div><p class="fine mt">計算上の確率は未校正です。楽天固有の価格差・ジャンプを十分に反映していません。期待値のプラスは利益の証明ではありません。</p></section>`;
}
function oddsResult(p,c,q,closed){return `<div class="spaced"><small>上になる計算上の確率</small><strong class="${p===null?'muted':'up'}">${p===null?'—':pct(p)}</strong></div><div class="progress"><i style="width:${p===null?0:p*100}%"></i></div><div class="two"><div><small>上：理論期待損益</small><p class="number ${c?sign(c.ev):'muted'}">${c?yen(c.ev):'—'}</p><small>損益分岐 ${c?pct(c.breakeven):'—'}</small></div><div><small>下：理論期待損益</small><p class="number ${q?sign(q.ev):'muted'}">${q?yen(q.ev):'—'}</p><small>損益分岐 ${q?pct(q.breakeven):'—'}</small></div></div>${closed?'<p class="watchhint mt">この回号は現在購入できる時間帯ではありません。</p>':''}`;}
function updateOdds(){let l=ladder();l[0]={strike:$('#strike')?.value||'',call:$('#callPrice')?.value||'',put:$('#putPrice')?.value||''};persist();let f=selectedRound()?forecast(selectedRound().expiry):null,p=l[0].strike&&f?E.probability(f,+l[0].strike,analysis.tick):null,c=E.payoff(p,l[0].call?+l[0].call:NaN),q=E.payoff(p===null?null:1-p,l[0].put?+l[0].put:NaN);$('#oddsResult').innerHTML=oddsResult(p,c,q,!!selectedRound()&&E.roundStatus(selectedRound(),Date.now())!=='購入可能');drawChart();}
function analysisLists(a){return [['確認した事実',a.facts],['推論',a.inference],['不確実な点',a.risks]].map(([t,arr])=>arr?.length?`<h3 class="mt">${t}</h3><ul class="list">${arr.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'').join('');}
function scenarioHTML(items){return items.length?`<div class="sep"></div><h3>イベントの条件別シナリオ</h3>${items.map(e=>`<div class="event"><b>${esc(e.title||e.eventId||'イベント')}</b><div class="scenarios"><div class="scenario"><strong class="up">予想を上回る場合</strong>${esc(e.above||'情報不足')}</div><div class="scenario"><strong class="down">予想を下回る場合</strong>${esc(e.below||'情報不足')}</div></div><p class="fine mt">${esc(e.base||'')}</p></div>`).join('')}`:'';}
function eventsPage(){
 const ev=relevantEvents().filter(e=>e.time===null||e.time>Date.now()-24*3600000);
 return `<div class="pagehead"><div><p class="eyebrow">EVENT CALENDAR</p><h1>経済・政治イベント</h1></div>${button('＋ 追加','addEvent','secondary')}</div><div class="banner">時刻は日本時間。BLSの公式予定と、GPTが検索した経済・政治イベントを表示します。時刻未定のニュースは時間軸に置きません。</div><div class="card"><div class="cardhead"><h2>${LABEL[state.pair]} 関連イベント</h2><select id="eventPair" aria-label="イベントの通貨ペア" style="width:130px;min-height:36px;padding:6px">${E.PAIRS.map(p=>`<option value="${p}" ${p===state.pair?'selected':''}>${LABEL[p]}</option>`).join('')}</select></div><div class="toolbar">${button(calendarLoading?'取得中…':'↻ BLS公式予定','calendar','secondary',calendarLoading?'disabled':'')}${button('✧ GPTで時事を調査','research','',working?'disabled':'')}</div><p class="fine mt">公式予定：${state.calendarAt?full(state.calendarAt)+' 取得':'未取得'}。BLSは米国指標のみ。金利・中央銀行・政治イベントはGPT調査で補完します。</p>${state.eventResearch?`<div class="note mt">${esc(state.eventResearch.summary||'調査済み')}<br><small>${full(state.eventResearch.time)} / 対象 ${esc(LABEL[state.eventResearch.pair]||state.eventResearch.pair)}</small></div>`:''}</div><section class="card">${ev.map(eventCard).join('')||'<div class="empty"><strong>予定はまだありません</strong><p>BLS公式予定を更新するか、GPTで時事を調査してください。</p></div>'}</section><p class="fine">発表日程の変更・中止・突発ニュースは反映が遅れる場合があります。発表値は自動取得しません。発表前の予測と、発表後の確認を分けて扱います。</p>`;
}
function eventCard(e){
 let past=e.time&&e.time<Date.now(),source=e.source==='bls'?'BLS公式':e.source==='manual'?'手動登録':e.source==='demo'?'デモ':'GPT検索';
 return `<article class="event"><div class="eventTop"><div class="eventTime">${e.time?time(e.time):'未定'}<small>${e.time?date(e.time):'日時要確認'}</small></div><div class="eventBody"><div class="toolbar">${pill(e.impact==='high'?'重要':e.impact==='medium'?'中':'低',e.impact==='high'?'amber':'')}${pill((e.currencies||[]).join(' / '))}${pill(past?'発表時刻通過':source)}</div><h3>${esc(e.title)}</h3><p class="fine">${esc(e.summary||'発表の詳細は出典を確認してください。')}</p>${e.forecast||e.previous?`<p class="fine mt">市場予想 ${esc(e.forecast||'未取得')} / 前回 ${esc(e.previous||'未取得')}</p>`:''}${e.source_url?`<button class="source" data-action="open" data-url="${esc(e.source_url)}">${source} · 出典を開く ↗</button>`:''}<div class="toolbar mt">${button('シナリオ・詳細','eventDetail','ghost small',`data-id="${esc(e.id)}"`)}${button('削除','deleteEvent','ghost small',`data-id="${esc(e.id)}"`)}</div></div></div></article>`;
}
function historyPage(){
 const history=state.history.filter(h=>h.pair===state.pair).slice().reverse(),market=currentMarket();let evaluated=[];for(const h of history.filter(h=>!h.demo)){let x=market&&!market.demo?E.evaluate(h,market.candles):[];evaluated.push(...x);}
 const n=evaluated.length,mae=n?E.mean(evaluated.map(x=>x.error)):null,coverage=n?E.mean(evaluated.map(x=>+x.covered)):null,bt=backtestResult;
 return historicalPanel()+`<div class="pagehead sectiongap"><div><p class="eyebrow">FORECAST JOURNAL</p><h1>予測精度の検証</h1></div>${button('書き出す','export','secondary')}</div><div class="pairbar">${E.PAIRS.map(p=>`<button class="pairbutton ${p===state.pair?'selected':''}" data-action="pair" data-pair="${p}">${LABEL[p]}</button>`).join('')}</div><div class="three"><div class="stat"><small>照合済みの予測点</small><strong>${n}</strong></div><div class="stat"><small>平均絶対誤差</small><strong>${fmt(mae)}</strong></div><div class="stat"><small>推定範囲内の実測</small><strong>${pct(coverage)}</strong></div></div><p class="fine mt">上は外部1分足との参考照合です。デモは除外。楽天の判定結果・取引利益ではありません。照合できる過去足がない予測は集計対象外です。</p>
 <section class="card sectiongap"><div class="cardhead"><h2>統計モデルの過去検証</h2>${button('30分先を検証','backtest','ghost small',!market?'disabled':'')}</div><p class="fine">各時点までの確定足だけで30分先を予測し、「価格が変わらない予測」と比較します。GPT・経済イベント・購入価格はこの検証に含みません。</p>${bt?`<div class="three mt"><div class="stat"><small>検証区間数</small><strong>${bt.n}</strong></div><div class="stat"><small>モデル誤差</small><strong>${fmt(bt.mae)}</strong></div><div class="stat"><small>変化なしの誤差</small><strong>${fmt(bt.naiveMAE)}</strong></div></div><p class="fine mt">範囲内 ${pct(bt.coverage)} / 方向一致 ${pct(bt.direction)}。${bt.n<30?'標本が少なく、優位性は判断できません。':'この標本だけで将来の優位性は判断できません。'} ${market?.demo?'デモの架空データによる検証です。':''}</p>`:''}</section>
 <section class="card"><div class="cardhead"><h2>${LABEL[state.pair]} の保存履歴</h2><span class="fine">${history.length}件</span></div>${history.map(h=>{let results=market&&!h.demo&&!market.demo?E.evaluate(h,market.candles):[],f=h.forecasts.find(f=>f.time===h.expiry);return `<div class="histrow"><div class="spaced"><div><strong>${full(h.generatedAt)}</strong><p class="fine">${h.source==='ai'?'GPT '+esc(h.model||''):'統計モデル'} · ${h.roundNumber?'第'+esc(h.roundNumber)+'回':'時間帯別'}${h.demo?' · デモ':''}</p></div>${button('詳細','record','ghost small',`data-id="${esc(h.id)}"`)}</div><div class="spaced mt"><span class="fine">基準 ${fmt(h.price)} → ${f?time(f.time)+' 予測':''}</span><strong>${f?fmt(f.p50):'—'}</strong></div><p class="fine mt">${results.length?'参考足と '+results.length+' 点を照合':'まだ参考価格と照合されていません'}${h.actualRakuten?' / 楽天判定 '+fmt(h.actualRakuten):''}</p></div>`;}).join('')||'<div class="empty"><strong>保存した予測がありません</strong><p>GPT分析は自動保存。統計予測は「予測を保存」で記録します。</p></div>'}</section>`;
}
